"""Render docs/RESULTS.generated.md and ROC/DET plots from results/*.json.

Never overwrites docs/RESULTS.md (the hand-curated file).
"""

from __future__ import annotations

import argparse
import json
from pathlib import Path

from liveness.reporting import SMOKE_MARK, plot_roc_det, render_results_table

_BANNER = (
    "<!-- Generated by scripts/render_results.py from results/*.json. Do not edit by hand. -->\n"
)


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--results-dir", type=Path, default=Path("results"))
    ap.add_argument("--out", type=Path, default=Path("docs/RESULTS.generated.md"))
    ap.add_argument("--plots-dir", type=Path, default=Path("results/plots"))
    args = ap.parse_args(argv)
    if args.out.name == "RESULTS.md":
        ap.error("refusing to overwrite the curated RESULTS.md")

    curves: dict[str, dict[str, list[float]]] = {}
    for path in sorted(args.results_dir.glob("*.json")):
        try:
            res = json.loads(path.read_text())
            blocks = (
                {"": res["test"]}
                if res["kind"] == "single"
                else {" (source)": res["source"]["test"], " (target)": res["target"]}
                if res["kind"] == "cross_dataset"
                else {}
            )
            tag = f" [{SMOKE_MARK}]" if res["data_kind"] == "synthetic_smoke" else ""
            for suffix, block in blocks.items():
                curves[f"{path.stem}{suffix}{tag}"] = block["roc"]
        except (ValueError, KeyError, TypeError):
            continue
    if curves:
        plot_roc_det(curves, args.plots_dir / "roc.png", args.plots_dir / "det.png")

    table = render_results_table(args.results_dir)
    args.out.parent.mkdir(parents=True, exist_ok=True)
    args.out.write_text(f"{_BANNER}\n# Results (generated)\n\n{table}")
    print(f"wrote {args.out}" + (f" and plots in {args.plots_dir}" if curves else ""))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
